    import heapq

    # Initialize a map to store the children of each element
    adj_list = {i: [] for i in range(1, N+1)}
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Initialize a list to store the negative path weight values in a priority queue
    neg_cycle = [] 
    for node in adj_list:
        queue = [(A[node-1], node)]
        while queue:
            total, start = heapq.heappop(queue)
            if total < 0:
                neg_cycle.append((total, start))
            for neighbor in adj_list[start]:
                if (total + A[neighbor-1]) < 0:
                    heapq.heappush(queue, (total + A[neighbor-1], neighbor))
    # Final answer
    if len(neg_cycle) > 0:
        return max([item[0] for item in neg_cycle])
    else:  
        return max(A)

``` 
